-- Critical rule: only the proof-aware public POS wrappers remain executable by
-- app roles. Legacy endpoints are private to SECURITY DEFINER wrappers so a
-- modified client cannot bypass proof binding by calling an older RPC directly.
revoke all on function public.pos_activate_device(text,text,text,text,text) from public, anon, authenticated;
revoke all on function public.pos_activate_device_v2(text,text,text,text,text) from public, anon, authenticated;
revoke all on function public.pos_device_heartbeat(text,text,text) from public, anon, authenticated;
revoke all on function public.pos_device_heartbeat_v2(text,text,text) from public, anon, authenticated;
revoke all on function public.pos_subscription_status(text) from public, anon, authenticated;
revoke all on function public.pos_subscription_status_v2(text,text) from public, anon, authenticated;
revoke all on function public.pos_owner_status(text,text) from public, anon, authenticated;
revoke all on function public.pos_provision_owner(text,text,text,text,text,text,text) from public, anon, authenticated;
revoke all on function public.pos_owner_login(text,text,text,text) from public, anon, authenticated;
revoke all on function public.pos_change_owner_password(text,text,text,text,text) from public, anon, authenticated;
revoke all on function public.pos_available_plans(text,text) from public, anon, authenticated;
revoke all on function public.pos_create_subscription_request(text,text,text,uuid,text) from public, anon, authenticated;
revoke all on function public.pos_pull_store_state(text,text) from public, anon, authenticated;
revoke all on function public.pos_push_store_state(text,text,jsonb) from public, anon, authenticated;
revoke all on function public.pos_push_store_state_v2(text,text,jsonb,bigint) from public, anon, authenticated;
revoke all on function public.pos_reserve_sequence_block(text,text,text,integer,bigint) from public, anon, authenticated;
revoke all on function public.pos_valid_business_for_device(text,text) from public, anon, authenticated;
revoke all on function public.pos_resolve_active_device(text,text) from public, anon, authenticated;

revoke all on function public.pos_activate_device_v3(text,text,text,text,text,text) from public;
revoke all on function public.pos_device_heartbeat_v3(text,text,text,text) from public;
revoke all on function public.pos_subscription_status_v3(text,text,text) from public;
revoke all on function public.pos_owner_status_v2(text,text,text) from public;
revoke all on function public.pos_provision_owner_v2(text,text,text,text,text,text,text,text) from public;
revoke all on function public.pos_owner_login_v2(text,text,text,text,text) from public;
revoke all on function public.pos_change_owner_password_v2(text,text,text,text,text,text) from public;
revoke all on function public.pos_available_plans_v2(text,text,text) from public;
revoke all on function public.pos_create_subscription_request_v2(text,text,text,text,uuid,text) from public;
revoke all on function public.pos_pull_store_state_v2(text,text,text) from public;
revoke all on function public.pos_push_store_state_v3(text,text,text,jsonb,bigint) from public;
revoke all on function public.pos_reserve_sequence_block_v2(text,text,text,text,integer,bigint) from public;

grant execute on function public.pos_activate_device_v3(text,text,text,text,text,text) to anon, authenticated;
grant execute on function public.pos_device_heartbeat_v3(text,text,text,text) to anon, authenticated;
grant execute on function public.pos_subscription_status_v3(text,text,text) to anon, authenticated;
grant execute on function public.pos_owner_status_v2(text,text,text) to anon, authenticated;
grant execute on function public.pos_provision_owner_v2(text,text,text,text,text,text,text,text) to anon, authenticated;
